(function(E){ const x = E["exam-04"] = E["exam-04"] || {units:{}}; (x.units = x.units || {})["x04-l2"] = {"id":"x04-l2","patterns":["L2-work"],"title":{"en":"Listening Part 2: a podcast","tr":"Listening Part 2: bir podcast","fa":"Listening Part 2: یک پادکست"},"objective":{"en":"In this lesson you will learn to choose TWO correct answers from five while a presenter corrects common ideas about an event, and to match six areas of the event to the right description from a box of seven.","tr":"Bu derste bir sunucu bir etkinlikle ilgili yaygın düşünceleri düzeltirken beş seçenekten doğru İKİ cevabı seçmeyi ve etkinliğin altı bölümünü yedi seçenekli bir kutudaki doğru tanımla eşleştirmeyi öğreneceksin.","fa":"در این درس یاد می‌گیری وقتی یک مجری باورهای رایج درباره‌ی یک برنامه را اصلاح می‌کند، از پنج گزینه دو جواب درست را انتخاب کنی و شش بخشِ آن برنامه را به توصیف درست از یک کادر هفت‌تایی وصل کنی."},"sessions":[["explain"],["drill"],["exit"]],"explain":{"title":{"en":"Listening Part 2: a podcast","tr":"Listening Part 2: bir podcast","fa":"Listening Part 2: یک پادکست"},"objective":{"en":"In this lesson you will learn to choose TWO correct answers from five while a presenter corrects common ideas about an event, and to match six areas of the event to the right description from a box of seven.","tr":"Bu derste bir sunucu bir etkinlikle ilgili yaygın düşünceleri düzeltirken beş seçenekten doğru İKİ cevabı seçmeyi ve etkinliğin altı bölümünü yedi seçenekli bir kutudaki doğru tanımla eşleştirmeyi öğreneceksin.","fa":"در این درس یاد می‌گیری وقتی یک مجری باورهای رایج درباره‌ی یک برنامه را اصلاح می‌کند، از پنج گزینه دو جواب درست را انتخاب کنی و شش بخشِ آن برنامه را به توصیف درست از یک کادر هفت‌تایی وصل کنی."},"stats":[{"label":{"en":"Questions","tr":"Soru","fa":"سؤال"},"value":"10"},{"label":{"en":"Speakers","tr":"Konuşan","fa":"گوینده"},"value":"1"},{"label":{"en":"Box","tr":"Kutu","fa":"کادر"},"value":"A-G"}],"context":{"eyebrow":{"en":"1 The context","tr":"1 Bağlam","fa":"۱ بافت"},"head":{"en":"This exam: a careers fair","tr":"Bu sınav: bir kariyer fuarı","fa":"این آزمون: یک نمایشگاه کاریابی"},"intro":{"en":"Part 2 is one speaker giving practical information. Work and careers come up often, sometimes as a radio show or podcast. The speaker moves through the event area by area, and each area has one key fact.","tr":"Part 2, pratik bilgi veren tek bir konuşmacıdır. İş ve kariyer sık çıkar, bazen bir radyo programı ya da podcast olarak. Konuşan etkinliği bölüm bölüm dolaşır ve her bölümün bir anahtar bilgisi vardır.","fa":"Part 2 یک گوینده است که اطلاعات کاربردی می‌دهد. کار و شغل زیاد می‌آید، گاهی به شکل برنامه‌ی رادیویی یا پادکست. گوینده برنامه را بخش به بخش می‌گوید و هر بخش یک واقعیت کلیدی دارد."},"technique":{"en":"2 The technique","tr":"2 Teknik","fa":"۲ تکنیک"},"labels":{"asks":{"en":"What this part is about","tr":"Bu kısım ne hakkında","fa":"این بخش درباره‌ی چیست"},"fields":{"en":"Headings you will see","tr":"Göreceğin başlıklar","fa":"عنوان‌هایی که می‌بینی"},"words":{"en":"Words that carry the answers","tr":"Cevabı taşıyan kelimeler","fa":"کلمه‌هایی که جواب را می‌آورند"},"a":{"en":"On the paper","tr":"Kâğıtta","fa":"روی برگه"},"b":{"en":"What you hear or read","tr":"Duyduğun ya da okuduğun","fa":"چیزی که می‌شنوی یا می‌خوانی"},"traps":{"en":"Traps","tr":"Tuzaklar","fa":"دام‌ها"},"example":{"en":"Example","tr":"Örnek","fa":"نمونه"},"ideas":{"en":"Ideas","tr":"Fikirler","fa":"ایده‌ها"}},"cards":[{"id":"x04-l2-ctx","exam":true,"patterns":["L2-work"],"often":{"pattern":"L2-work","n":9,"of":40,"label":{"en":"Comes up often in the real exam: 9 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 9’unda","fa":"در آزمون واقعی زیاد می‌آید: در ۹ آزمون از ۴۰ آزمونِ اخیر"}},"title":{"en":"A podcast about a careers fair","tr":"Bir kariyer fuarı hakkında bir podcast","fa":"پادکستی درباره‌ی یک نمایشگاه کاریابی"},"asks":{"en":"A presenter previews an annual careers fair: facts about this year’s event, advice for visitors, and what is special about each area of the fair.","tr":"Bir sunucu yıllık bir kariyer fuarını tanıtıyor: bu yılki etkinlikle ilgili bilgiler, ziyaretçilere tavsiyeler ve fuarın her bölümünün neyle öne çıktığı.","fa":"یک مجری یک نمایشگاه سالانه‌ی کاریابی را معرفی می‌کند: اطلاعاتی درباره‌ی برنامه‌ی امسال، توصیه به بازدیدکننده‌ها و اینکه هر بخش نمایشگاه چه ویژگی‌ای دارد."},"fields":["This year’s fair","Getting there","Advice for visitors","The areas of the fair"],"words":[{"a":"free","b":"there is no charge / you don’t pay","tr":"ücretsiz","fa":"رایگان"},{"a":"exhibitors","b":"organisations taking part","tr":"katılımcı kuruluşlar","fa":"شرکت‌کننده‌های نمایشگاه"},{"a":"venue","b":"the place where it is held","tr":"mekân","fa":"محل برگزاری"},{"a":"a rumour","b":"something people say that may not be true","tr":"söylenti","fa":"شایعه"},{"a":"shuttle bus","b":"a bus that goes back and forth","tr":"servis otobüsü","fa":"اتوبوس رفت‌وبرگشتی"},{"a":"smart casual","b":"neat but not formal","tr":"şık ama rahat","fa":"مرتب ولی نه رسمی"},{"a":"stress","b":"say that something is important","tr":"vurgulamak","fa":"تأکید کردن"},{"a":"discontinued","b":"no longer available","tr":"artık sunulmayan","fa":"دیگر ارائه نمی‌شود"},{"a":"book in advance","b":"reserve a place before you go","tr":"önceden yer ayırtmak","fa":"از قبل جا رزرو کردن"},{"a":"aimed at","b":"intended for","tr":"... yönelik","fa":"مخصوصِ"},{"a":"highlight","b":"the best part","tr":"en dikkat çekici bölüm","fa":"نقطه‌ی برجسته"},{"a":"gets crowded","b":"a lot of people go there","tr":"kalabalık olur","fa":"شلوغ می‌شود"}],"traps":[{"en":"\"A lot of people assume...\" and \"some of you have heard...\" bring in ideas the speaker then corrects. Wait for \"It isn’t\" or \"that was only a rumour\".","tr":"\"Birçok insan ... sanıyor\" ve \"bazılarınız ... duymuştur\" konuşanın sonra düzelttiği fikirleri getirir. \"It isn’t\" ya da \"that was only a rumour\" ifadesini bekle.","fa":"«خیلی‌ها فکر می‌کنند...» و «بعضی از شما شنیده‌اید...» ایده‌هایی را می‌آورند که گوینده بعد اصلاح می‌کند. منتظر «It isn’t» یا «that was only a rumour» بمان."},{"en":"In the matching task, one option is mentioned but belongs somewhere else (\"those only happen at another event\"). Match only what is true of that area.","tr":"Eşleştirmede bir seçenekten söz edilir ama başka bir yere aittir (\"onlar yalnızca başka bir etkinlikte olur\"). Yalnızca o bölüm için doğru olanı eşleştir.","fa":"در جورکردن از یک گزینه حرف زده می‌شود اما مال جای دیگری است («آن‌ها فقط در یک برنامه‌ی دیگر هستند»). فقط چیزی را وصل کن که درباره‌ی همان بخش درست است."}],"example":{"lines":[["Presenter","You might think you need a ticket for the talks. You don’t: just turn up, although the seats fill quickly."]],"item":"What does the presenter say about the talks? A You need a ticket. B You can just turn up. C They are rarely full.","answer":"B","why":{"en":"The ticket is what \"you might think\". \"Just turn up\" is the fact; the seats fill quickly, so C is wrong.","tr":"Bilet \"düşünebileceğin\" şey. \"Gelmen yeterli\" gerçek; koltuklar çabuk doluyor, yani C yanlış.","fa":"بلیت چیزی است که «شاید فکر کنی». «فقط بیا» واقعیت است؛ صندلی‌ها زود پر می‌شوند، پس C غلط است."}}},{"id":"L2-work","ctx":["L2-work"],"title":{"en":"Work talks: induction, training and careers","tr":"İş konuşmaları: oryantasyon, eğitim ve kariyer","fa":"صحبت‌های کاری: آشنایی، آموزش و شغل"},"asks":{"en":"A manager welcomes new staff, a trainer explains a job, or someone talks about a career. Questions ask about duties, rules, who is responsible for what, what the job needs and advice for new starters.","tr":"Bir yönetici yeni personeli karşılar, bir eğitmen işi anlatır ya da biri bir kariyerden söz eder. Sorular görevleri, kuralları, kimin neden sorumlu olduğunu, işin ne gerektirdiğini ve yeni başlayanlara tavsiyeleri sorar.","fa":"یک مدیر به کارکنان تازه خوش‌آمد می‌گوید، یک مربی کاری را توضیح می‌دهد، یا کسی درباره‌ی یک شغل حرف می‌زند. سؤال‌ها درباره‌ی وظایف، قانون‌ها، اینکه چه کسی مسئول چیست، شرایط کار و توصیه به تازه‌کارهاست."},"fields":["What should new staff do on the first day?","Who should staff report problems to?","What is the most important quality for this job?","Which TWO things must staff bring?","What is each person responsible for?","What advice does the speaker give?"],"words":[{"a":"induction","b":"your first day / the welcome session","tr":"oryantasyon","fa":"دوره‌ی آشنایی"},{"a":"rota","b":"the timetable of who works when","tr":"vardiya çizelgesi","fa":"جدول شیفت‌ها"},{"a":"report to","b":"the person you go to","tr":"... -e bağlı olmak","fa":"زیر نظر ... بودن"},{"a":"responsible for","b":"in charge of / looks after","tr":"... -den sorumlu","fa":"مسئولِ"},{"a":"health and safety","b":"the rules that stop accidents","tr":"iş sağlığı ve güvenliği","fa":"ایمنی و بهداشت کار"},{"a":"essential","b":"the one thing you must have","tr":"şart","fa":"ضروری"},{"a":"mentor","b":"an experienced colleague who helps you","tr":"deneyimli rehber, mentor","fa":"همکار باتجربه‌ی راهنما"},{"a":"sign in","b":"write your name when you arrive","tr":"giriş kaydı yapmak","fa":"ثبت ورود"},{"a":"overtime","b":"extra hours","tr":"fazla mesai","fa":"اضافه‌کاری"},{"a":"feedback","b":"we tell you how you're doing","tr":"geri bildirim","fa":"بازخورد"},{"a":"promotion","b":"a better job later on","tr":"terfi","fa":"ترفیع"},{"a":"qualification","b":"a certificate / training in","tr":"nitelik, diploma","fa":"مدرک"}],"traps":[{"en":"Names and roles: several people are introduced. Match each one by what they do, not by the order you hear them.","tr":"İsimler ve görevler: birkaç kişi tanıtılır. Her birini duyduğun sıraya göre değil, yaptığı işe göre eşleştir.","fa":"اسم‌ها و نقش‌ها: چند نفر معرفی می‌شوند. هر کدام را با کاری که می‌کند جور کن، نه با ترتیبی که می‌شنوی."},{"en":"\"Most important\" against \"also useful\": several qualities are mentioned, but one is stressed.","tr":"\"En önemli\" ile \"bu da işe yarar\": birkaç nitelik söylenir ama biri vurgulanır.","fa":"«مهم‌ترین» در برابر «این هم مفید است»: چند ویژگی گفته می‌شود، ولی روی یکی تأکید می‌شود."},{"en":"Rules that changed: \"you used to..., but from now on...\". The answer is the new rule.","tr":"Değişen kurallar: \"eskiden..., ama artık...\". Cevap yeni kuraldır.","fa":"قانون‌هایی که عوض شده‌اند: «قبلاً...، ولی از این به بعد...». جواب قانون جدید است."}],"example":{"lines":[["Manager","Lots of people think you need a chef’s training for this job."],["Manager","You don’t. Speed comes with time, too."],["Manager","What really matters is staying calm when the kitchen gets busy."]],"item":"What does the manager say is most important?  A cooking qualifications   B staying calm under pressure   C working fast","answer":"B","why":{"en":"Training is rejected and speed \"comes with time\". \"What really matters\" stresses staying calm.","tr":"Eğitim gereksiz deniyor, hız da \"zamanla gelir\". \"What really matters\" sakin kalmayı vurguluyor.","fa":"آموزش آشپزی لازم نیست و سرعت «با زمان می‌آید». «What really matters» روی آرام ماندن تأکید می‌کند."}},"general":true,"patterns":["L2-work"],"often":{"pattern":"L2-work","n":9,"of":40,"label":{"en":"Comes up often in the real exam: 9 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 9’unda","fa":"در آزمون واقعی زیاد می‌آید: در ۹ آزمون از ۴۰ آزمونِ اخیر"}}}]},"points":[{"eyebrow":{"en":"In the exam","tr":"Sınavda","fa":"در آزمون"},"head":{"en":"Two pairs, then a box of seven","tr":"İki çift soru, sonra yedili bir kutu","fa":"دو جفت سؤال، بعد یک کادر هفت‌تایی"},"body":{"en":"Questions 11-12 and 13-14 each ask for TWO letters, A-E. After a short break, Questions 15-20 list six areas; choose the right description for each from a box of seven, A-G, so one letter is not used.","tr":"Soru 11-12 ve 13-14’ün her biri A-E arasından İKİ harf ister. Kısa bir aradan sonra Soru 15-20 altı bölüm sıralar; her biri için A-G arasındaki yedi seçenekten doğru tanımı seç; bir harf kullanılmaz.","fa":"سؤال‌های ۱۱-۱۲ و ۱۳-۱۴ هر کدام دو حرف از A تا E می‌خواهند. بعد از یک مکث کوتاه، سؤال‌های ۱۵ تا ۲۰ شش بخش را فهرست می‌کنند؛ برای هر کدام توصیف درست را از کادر هفت‌تایی A تا G انتخاب کن، پس یک حرف استفاده نمی‌شود."}},{"eyebrow":{"en":"The method","tr":"Yöntem","fa":"روش"},"head":{"en":"One area, one fact","tr":"Bir bölüm, bir bilgi","fa":"یک بخش، یک واقعیت"},"steps":[{"en":"In the break, read the seven descriptions and note a key word for each: new, crowded, book, moved.","tr":"Arada yedi tanımı oku ve her biri için bir anahtar kelime not et: new, crowded, book, moved.","fa":"در مکث، هفت توصیف را بخوان و برای هر کدام یک کلیدواژه یادداشت کن: new، crowded، book، moved."},{"en":"The areas come in order. When the speaker names the next area, move your eyes down.","tr":"Bölümler sırayla gelir. Konuşan bir sonraki bölümün adını söyleyince gözünü aşağı kaydır.","fa":"بخش‌ها به ترتیب می‌آیند. وقتی گوینده اسم بخش بعدی را می‌گوید، نگاهت را پایین ببر."},{"en":"Listen for the same idea in other words: \"the first time the fair has had\" = new.","tr":"Aynı fikri başka kelimelerle dinle: \"the first time the fair has had\" = new.","fa":"همان ایده را با کلمه‌های دیگر بشنو: «the first time the fair has had» یعنی new."}]},{"eyebrow":{"en":"The trap","tr":"Tuzak","fa":"دام"},"head":{"en":"Common beliefs, corrected","tr":"Yaygın inanışlar, düzeltilmiş","fa":"باورهای رایج، اصلاح‌شده"},"body":{"en":"A presenter often starts with what listeners expect: that tickets cost money, that the place has moved, that you should arrive early. Then comes the fact. In a choose-TWO question, tick only the options that survive the correction.","tr":"Sunucu çoğu zaman dinleyicilerin beklediğiyle başlar: biletlerin paralı olduğu, yerin değiştiği, erken gelmen gerektiği. Sonra gerçek gelir. İki seçenekli soruda yalnızca düzeltmeden sağ çıkan seçenekleri işaretle.","fa":"مجری اغلب با چیزی شروع می‌کند که شنونده‌ها انتظار دارند: اینکه بلیت پولی است، جا عوض شده، باید زود بروی. بعد واقعیت می‌آید. در سؤال «دو گزینه» فقط گزینه‌هایی را علامت بزن که بعد از اصلاح هنوز درست‌اند."}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"One area, step by step","tr":"Bir bölüm, adım adım","fa":"یک بخش، قدم به قدم"},"instruction":"What does the presenter say about the Science Tent? Box: A It is new.  B It closes early.  C You must book.","item":"Science Tent","lines":[["Presenter","The Science Tent was a huge success last year, so it’s back, bigger than before. You don’t need to book, but it does close at three."]],"answer":"B","walk":[{"en":"\"It’s back\" means it is not new: A is out.","tr":"\"It’s back\" yeni olmadığı anlamına gelir: A elenir.","fa":"«It’s back» یعنی جدید نیست: A رد می‌شود."},{"en":"\"You don’t need to book\": C is out.","tr":"\"Rezervasyona gerek yok\": C elenir.","fa":"«لازم نیست رزرو کنی»: C رد می‌شود."},{"en":"\"It does close at three\" = closes early: B.","tr":"\"Saat üçte kapanıyor\" = erken kapanıyor: B.","fa":"«ساعت سه بسته می‌شود» یعنی زود بسته می‌شود: B."}]},"quick":{"prompt":"You hear: \"Many people think the talks are only for graduates. In fact, anyone can come, and the first talk is aimed at parents.\" Which is true?","options":["The talks are only for graduates.","The first talk is for graduates.","Parents are welcome at the talks."],"correct":2,"why":{"en":"\"Many people think\" gives the wrong idea; \"in fact, anyone can come\" and the first talk is \"aimed at parents\".","tr":"\"Many people think\" yanlış fikri verir; \"aslında herkes gelebilir\" ve ilk konuşma \"ebeveynlere yönelik\".","fa":"«خیلی‌ها فکر می‌کنند» ایده‌ی غلط را می‌دهد؛ «در واقع همه می‌توانند بیایند» و سخنرانی اول «مخصوص والدین» است."}},"remember":{"en":"Tick only what survives the correction, and give each area the one fact the speaker stresses.","tr":"Yalnızca düzeltmeden sağ çıkanı işaretle ve her bölüme konuşanın vurguladığı tek bilgiyi ver.","fa":"فقط چیزی را علامت بزن که بعد از اصلاح درست می‌ماند و به هر بخش همان یک واقعیتی را بده که گوینده رویش تأکید می‌کند."},"type":"explain","id":"c-x04-l2-e","course":"ielts-exams","exam":"exam-04","unit":"x04-l2"},"drill":{"type":"drill","skill":"listening","part":"Listening Part 2","title":{"en":"Next Step: the Kelso Careers Fair","tr":"Next Step: Kelso Kariyer Fuarı","fa":"Next Step: نمایشگاه کاریابی کلسو"},"timed":7,"ctx":["L2-work"],"script":[{"who":"Presenter","line":"Hello and welcome to Next Step, the podcast for anyone thinking about their future career. I'm Ravi, and this week I'm talking about something many of you have been asking about: the Kelso Careers Fair, which takes place at the Kelso Exhibition Centre over the weekend of the fourteenth and fifteenth of March."},{"who":"Presenter","line":"First, some good news. A lot of people assume that because the fair has grown, it must be charging for tickets now. It isn't. Entry is still completely free, for everyone. And it really has grown: last year there were about a hundred and fifty organisations taking part, and this year there'll be more than two hundred. Some of you have heard it's moving to a new venue, but that was only a rumour; it's in the same place as always."},{"who":"Presenter","line":"It runs for two days, not three as it did once, and you'll need to plan your journey, because the car park charges by the hour. The simplest option is the free shuttle bus, which leaves from the railway station every fifteen minutes."},{"who":"Presenter","line":"Now, some advice. I spoke to several of the organisers, and they all said the same thing: bring printed copies of your CV. Many employers will take them away and read them properly after the fair, which they simply won't do with a link on your phone. You don't need to dress formally; smart casual is perfectly fine."},{"who":"Presenter","line":"The other thing they stressed is to prepare some questions before you go. Employers say the visitors they remember are the ones who ask something specific, like what a typical first year in the job looks like, rather than just picking up a leaflet. Oh, and most people think you should arrive the moment the doors open. Actually, the morning is the busiest time. If you come after lunch, the queues are much shorter and the staff have more time to talk. And the fair app has been discontinued this year, so pick up a paper map at the entrance."},{"who":"Presenter","line":"Right, let me take you through the main areas of the fair, because there are a few changes."},{"who":"Presenter","line":"The Engineering Hall has always been at the front of the main building, but it's grown so much that this year it's been moved across the road into the sports hall. Follow the signs from the entrance."},{"who":"Presenter","line":"In the Health Zone, the big attraction is the CV clinic, where a careers adviser will look at your CV with you for fifteen minutes. People sometimes expect free taster sessions there, like using hospital equipment, but those only happen at the hospital's own open day. The CV clinic is very popular, so you'll need to book a place in advance through the fair website."},{"who":"Presenter","line":"The Creative Industries tent is something completely new. It's the first time the fair has had a space just for film, games, design and music, and I think it's going to be one of the highlights."},{"who":"Presenter","line":"The Apprenticeship Corner is really aimed at younger visitors. If you're still at school and you're wondering whether you have to go to university, this is the place to start. The people there are used to talking to fifteen- and sixteen-year-olds and their parents."},{"who":"Presenter","line":"The Graduate Employers' Hall is where the big companies are, and I'll be honest, it gets extremely crowded, especially on Saturday. If you only have a short time, go there on Sunday."},{"who":"Presenter","line":"And finally, the Volunteering Stand, run by local charities. It's a great place to find out how to get experience while you study. Just be aware that it closes early, at two o'clock on both days, because the volunteers who run it have their own projects to get back to."},{"who":"Presenter","line":"So that's the fair. I'll be there on the Saturday, recording interviews for next week's episode, so come and say hello. And if you have a question you would like me to put to any of the employers, send it in through the website before Friday."}],"groups":[{"instruction":"Questions 11-12. Choose TWO letters, A-E.","qtype":"mcq2","questions":[{"n":11,"n2":12,"kind":"mcq2","prompt":"Which TWO things does Ravi say about this year’s fair?","options":["A It has moved to a new venue.","B Visitors do not have to pay to enter.","C It lasts for three days.","D Parking at the venue is free.","E More organisations are taking part than last year."],"correct":[1,4],"evidence":"Entry is still completely free","trap":["TR-ruledout","TR-paraphrase"],"why":{"en":"B \"Entry is still completely free\" and E \"more than two hundred\" this year against about 150 last year. The new venue was \"only a rumour\", it runs for two days, and the car park charges by the hour.","tr":"B \"Giriş hâlâ tamamen ücretsiz\" ve E bu yıl geçen yılki yaklaşık 150’ye karşı \"iki yüzden fazla\". Yeni mekân \"yalnızca bir söylenti\", fuar iki gün sürüyor ve otopark saatlik ücretli.","fa":"B «ورود هنوز کاملاً رایگان است» و E امسال «بیش از دویست» در برابر حدود ۱۵۰ در سال قبل. محل جدید «فقط یک شایعه بود»، نمایشگاه دو روز است و پارکینگ ساعتی پول می‌گیرد."}}]},{"instruction":"Questions 13-14. Choose TWO letters, A-E.","qtype":"mcq2","questions":[{"n":13,"n2":14,"kind":"mcq2","prompt":"Which TWO pieces of advice does Ravi give to visitors?","options":["A Wear formal clothes.","B Have paper versions of your CV with you.","C Arrive as soon as the doors open.","D Prepare some questions for employers.","E Download the fair app before you go."],"correct":[1,3],"evidence":"bring printed copies of your CV","trap":["TR-ruledout"],"why":{"en":"B \"bring printed copies of your CV\" and D \"prepare some questions before you go\". Smart casual is fine, the morning is the busiest time, and the app has been discontinued.","tr":"B \"özgeçmişinin basılı kopyalarını getir\" ve D \"gitmeden önce birkaç soru hazırla\". Şık ama rahat giyim yeterli, sabah en yoğun zaman ve uygulama kaldırıldı.","fa":"B «نسخه‌ی چاپی رزومه‌ات را بیاور» و D «قبل از رفتن چند سؤال آماده کن». لباس مرتب ولی غیررسمی کافی است، صبح شلوغ‌ترین زمان است و اپلیکیشن کنار گذاشته شده."}}]},{"instruction":"Questions 15-20. What does Ravi say about each of the following areas of the fair? Choose SIX answers from the box and write the correct letter, A-G, next to Questions 15-20.","qtype":"matching","bank":["A It is new this year.","B It is usually very crowded.","C Visitors need to book in advance.","D It offers free taster sessions.","E It has moved to a different building.","F It is especially suitable for school students.","G It closes early."],"questions":[{"n":15,"kind":"match","prompt":"Engineering Hall","correct":4,"evidence":"it's been moved across the road into the sports hall","why":{"en":"\"It’s been moved across the road into the sports hall\": a different building.","tr":"\"Yolun karşısındaki spor salonuna taşındı\": başka bir bina.","fa":"«به سالن ورزشیِ آن طرف خیابان منتقل شده»: یک ساختمان دیگر."},"trap":["TR-paraphrase"]},{"n":16,"kind":"match","prompt":"Health Zone","correct":2,"evidence":"you'll need to book a place in advance","why":{"en":"Taster sessions \"only happen at the hospital’s own open day\" (D is ruled out). The CV clinic must be booked in advance.","tr":"Deneme seansları \"yalnızca hastanenin kendi açık gününde oluyor\" (D eleniyor). Özgeçmiş kliniği önceden ayırtılmalı.","fa":"جلسه‌های آزمایشی «فقط در روز درهای باز خود بیمارستان است» (D رد می‌شود). کلینیک رزومه را باید از قبل رزرو کرد."},"trap":["TR-ruledout"]},{"n":17,"kind":"match","prompt":"Creative Industries tent","correct":0,"evidence":"It's the first time the fair has had a space just for film","why":{"en":"\"Something completely new... the first time the fair has had\" such a space: new this year.","tr":"\"Tamamen yeni bir şey... fuarın ilk kez\" böyle bir alanı var: bu yıl yeni.","fa":"«چیزی کاملاً تازه... اولین بار است که نمایشگاه» چنین فضایی دارد: امسال جدید است."},"trap":["TR-paraphrase"]},{"n":18,"kind":"match","prompt":"Apprenticeship Corner","correct":5,"evidence":"really aimed at younger visitors","why":{"en":"\"Really aimed at younger visitors... if you’re still at school\": suitable for school students.","tr":"\"Gerçekten daha genç ziyaretçilere yönelik... hâlâ okuldaysan\": okul öğrencilerine uygun.","fa":"«واقعاً مخصوص بازدیدکننده‌های جوان‌تر... اگر هنوز مدرسه می‌روی»: مناسب دانش‌آموزها."},"trap":["TR-paraphrase"]},{"n":19,"kind":"match","prompt":"Graduate Employers’ Hall","correct":1,"evidence":"it gets extremely crowded","why":{"en":"\"It gets extremely crowded, especially on Saturday.\"","tr":"\"Özellikle cumartesi aşırı kalabalık oluyor.\"","fa":"«خیلی شلوغ می‌شود، مخصوصاً شنبه»."},"trap":["TR-paraphrase"]},{"n":20,"kind":"match","prompt":"Volunteering Stand","correct":6,"evidence":"at two o'clock on both days","why":{"en":"\"It closes early, at two o’clock on both days.\"","tr":"\"Erken kapanıyor, iki gün de saat ikide.\"","fa":"«زود بسته می‌شود، هر دو روز ساعت دو»."},"trap":["TR-paraphrase"]}]}],"audio":{"voices":{"Announcer":{"accent":"British (standard Southern)","gender":"M","tts":{"engine":"kokoro","voice":"bm_george"},"role":"Recorded rubric"},"Presenter":{"accent":"Australian","gender":"M","tts":{"engine":"kokoro","voice":"bm_daniel","fallback":true,"note":"Australian wanted; no free Australian voice yet"},"role":"Podcast presenter"}},"sequence":[{"type":"announcer","text":"Part 2. You will hear a podcast presenter talking about an annual careers fair. First, you have some time to look at Questions 11 to 14."},{"type":"pause","seconds":30,"note":"reading time, Questions 11-14"},{"type":"announcer","text":"Now listen carefully and answer Questions 11 to 14."},{"type":"sfx","note":"short podcast jingle (2 s) under the first line"},{"type":"lines","from":0,"to":4},{"type":"announcer","text":"Before you hear the rest of the podcast, you have some time to look at Questions 15 to 20."},{"type":"pause","seconds":30,"note":"reading time, Questions 15-20"},{"type":"announcer","text":"Now listen and answer Questions 15 to 20."},{"type":"lines","from":5,"to":12},{"type":"announcer","text":"That is the end of Part 2. You now have half a minute to check your answers.","after":30}]},"id":"c-x04-l2-d","course":"ielts-exams","exam":"exam-04","unit":"x04-l2"},"exit":{"type":"exit","items":[{"tests":"word","point":1,"prompt":"If a service has been \"discontinued\", it...","options":["has become cheaper","is no longer available","is only for members"],"correct":1,"why":{"en":"Discontinued = stopped; you cannot use it any more.","tr":"Discontinued = durduruldu; artık kullanamazsın.","fa":"discontinued یعنی متوقف شده؛ دیگر نمی‌توانی از آن استفاده کنی."}},{"tests":"paraphrase","point":3,"prompt":"Which phrase means \"it is new this year\"?","options":["it’s the first time we’ve had one","it’s back again","it’s been there for years"],"correct":0,"why":{"en":"\"The first time we’ve had one\" = new. \"It’s back\" means it existed before.","tr":"\"İlk kez böyle bir şeyimiz var\" = yeni. \"It’s back\" daha önce de var olduğunu gösterir.","fa":"«اولین بار است که یکی داریم» یعنی جدید. «It’s back» یعنی قبلاً هم بوده."}},{"tests":"method","point":2,"prompt":"Six areas and a box of seven descriptions. What does this tell you?","options":["one area has two answers","each letter is used once and one area has no answer","one description will not be used"],"correct":2,"why":{"en":"Six questions, seven options, each letter at most once: one is left over.","tr":"Altı soru, yedi seçenek, her harf en fazla bir kez: biri artar.","fa":"شش سؤال، هفت گزینه، هر حرف حداکثر یک بار: یکی اضافه می‌ماند."}},{"tests":"trap","point":3,"prompt":"\"Some of you have heard the fair is moving to the stadium. That was only a rumour.\" Where is the fair?","options":["at the stadium","in the same place as before","nobody knows yet"],"correct":1,"why":{"en":"\"Only a rumour\" means the move is not true.","tr":"\"Yalnızca bir söylenti\" taşınmanın doğru olmadığını gösterir.","fa":"«فقط یک شایعه» یعنی جابه‌جایی درست نیست."}},{"tests":"trap","point":2,"prompt":"\"People expect free samples at the food stand, but those are only at the Saturday market.\" Does the food stand offer free samples?","options":["No","Yes","Only on Saturdays"],"correct":0,"why":{"en":"Free samples belong to a different event, not to this stand.","tr":"Ücretsiz numuneler bu standa değil, başka bir etkinliğe ait.","fa":"نمونه‌ی رایگان مال برنامه‌ی دیگری است، نه این غرفه."}}],"id":"c-x04-l2-x","course":"ielts-exams","exam":"exam-04","unit":"x04-l2"}}; })(globalThis.IELTS_EXAMS = globalThis.IELTS_EXAMS || {});
